// Context-style delivery: every consumer re-renders when the value changes.
// Store-style delivery: each subscriber has a selector and re-renders only if its slice changed.
let state = { cart: 1, search: "a" };
const renders = { contextConsumer: 0, selectorCart: 0, selectorSearch: 0 };

const subs = [];
function subscribe(selector, onChange) {
  let last = selector(state);
  subs.push(() => {
    const next = selector(state);
    if (!Object.is(next, last)) { last = next; onChange(); } // compare slice with ===
  });
}
function setState(patch) {
  state = { ...state, ...patch };      // new object identity, like a new Provider value
  renders.contextConsumer++;           // context: all consumers re-render on any change
  subs.forEach(fn => fn());            // store: only changed slices notify
}
subscribe(s => s.cart, () => renders.selectorCart++);
subscribe(s => s.search, () => renders.selectorSearch++);

for (const t of ["an", "ann", "anna"]) setState({ search: t }); // 3 keystrokes, cart untouched
console.log("keystrokes: 3, cart never changed");
console.log("context consumer of cart re-rendered:", renders.contextConsumer);
console.log("selector on cart re-rendered:", renders.selectorCart);
console.log("selector on search re-rendered:", renders.selectorSearch);

// A tiny Redux: dispatch -> middleware -> reducer -> notify subscribers.
function createStore(reducer, middlewares) {
  let state = reducer(undefined, { type: "@@init" });
  const listeners = [];
  let dispatch = action => {
    const next = reducer(state, action);      // reducer is pure, returns new state
    if (next !== state) { state = next; listeners.forEach(l => l()); }
  };
  for (const mw of [...middlewares].reverse()) {
    const inner = dispatch;
    dispatch = mw(() => state)(inner);        // wrap dispatch in order
  }
  return { dispatch: a => dispatch(a), getState: () => state, subscribe: l => listeners.push(l) };
}
function cart(state = { items: [] }, action) {
  if (action.type === "cart/added") return { items: [...state.items, action.payload] };
  return state;                                // unknown action: same reference
}
const logger = getState => next => action => {
  console.log("middleware saw:", action.type);
  next(action);
  console.log("state after:", JSON.stringify(getState()));
};
const store = createStore(cart, [logger]);
store.subscribe(() => console.log("subscriber notified"));
store.dispatch({ type: "cart/added", payload: "book" });
const before = store.getState();
store.dispatch({ type: "unknown" });
console.log("same ref after unknown action:", store.getState() === before);

// Stale-while-revalidate with staleTime, like React Query in miniature.
let now = 0;                       // fake clock in seconds
const cache = new Map();           // key -> { data, at }
const staleTime = 10;
let serverVersion = 1;
const fetchFromServer = () => "v" + serverVersion;

function useQuery(key) {
  const entry = cache.get(key);
  if (!entry) {                    // nothing cached: the user must wait
    const data = fetchFromServer();
    cache.set(key, { data, at: now });
    console.log(`t=${now} miss  -> fetched ${data}`);
    return data;
  }
  if (now - entry.at < staleTime) {  // fresh: no request at all
    console.log(`t=${now} fresh -> ${entry.data}, no request`);
    return entry.data;
  }
  console.log(`t=${now} stale -> show ${entry.data} now, refetch in background`);
  const data = fetchFromServer();    // background refresh, then swap in
  cache.set(key, { data, at: now });
  console.log(`t=${now} background refetch done -> ${data}`);
  return entry.data;                 // this render shows the old value instantly
}
useQuery("product:1");
now = 5; useQuery("product:1");
serverVersion = 2; now = 12; useQuery("product:1");
now = 13; useQuery("product:1");

// Optimistic like: snapshot, write expected value, roll back on error.
let cache = { post: { liked: false, count: 10 } };
const serverOk = { value: false };
const sleep = ms => new Promise(r => setTimeout(r, ms));

async function likeMutation() {
  const snapshot = cache;                              // onMutate: keep old value
  cache = { post: { liked: true, count: snapshot.post.count + 1 } }; // new object, no mutation
  console.log("optimistic:", JSON.stringify(cache.post));
  try {
    await sleep(10);
    if (!serverOk.value) throw new Error("500");
    console.log("server confirmed");
  } catch (e) {
    cache = snapshot;                                  // onError: roll back
    console.log("error", e.message, "-> rolled back:", JSON.stringify(cache.post));
  } finally {
    console.log("onSettled: refetch to match the server");
  }
}
(async () => {
  console.log("before:", JSON.stringify(cache.post));
  await likeMutation();       // fails
  serverOk.value = true;
  await likeMutation();       // succeeds
  console.log("final:", JSON.stringify(cache.post));
})();

// Out-of-order responses: naive vs latest-request-id guard.
const delays = { a: 30, an: 20, ann: 10 };   // older requests are slower
const fakeFetch = q => new Promise(r => setTimeout(() => r("results for " + q), delays[q]));

async function run(guarded) {
  let shown = "";
  let latest = 0;
  const search = async q => {
    const id = ++latest;
    const res = await fakeFetch(q);
    if (guarded && id !== latest) { console.log("  ignored stale:", res); return; }
    shown = res;                                // naive version always overwrites
  };
  const all = ["a", "an", "ann"].map(search);   // three keystrokes in a row
  await Promise.all(all);
  console.log(guarded ? "guarded shows:" : "naive shows:  ", shown);
}
(async () => { await run(false); await run(true); })();

// A store with subscribe/getSnapshot, the shape useSyncExternalStore expects.
function createStore(initial) {
  let state = initial;
  const listeners = new Set();
  return {
    getSnapshot: () => state,
    subscribe: l => { listeners.add(l); return () => listeners.delete(l); },
    set(patch) { state = { ...state, ...patch }; listeners.forEach(l => l()); },
  };
}
// Like a Zustand selector hook: re-render only when the selected slice changes (Object.is).
function useSelector(store, selector, label) {
  let last = selector(store.getSnapshot());
  console.log(label, "initial render:", last);
  store.subscribe(() => {
    const next = selector(store.getSnapshot());
    if (!Object.is(next, last)) { last = next; console.log(label, "re-render:", next); }
  });
}
